reference_solution:
def baseball_score(ops):
    scores = []
    for operation in ops:
        if operation == 'C': scores.pop()
        elif operation == 'D': scores.append(2 * scores[-1])
        elif operation == '+': scores.append(scores[-1] + scores[-2])
        else: scores.append(int(operation))
    return sum(scores)

